export const STORAGE_KEY = 'register_progress';

const loadSavedData = (): RegisterFormData => {
  try {
    const saved = sessionStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved) as Partial<RegisterFormData>;
      if (parsed.birthday) {
        parsed.birthday = new Date(parsed.birthday as unknown as string);
      }
      return { ...initialData, ...parsed };
    }
  } catch (e) {
    console.log(e);
  }
  return initialData;
};

const saveData = (data: RegisterFormData): void => {
  try {
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    const { offerImages, ...rest } = data;
    sessionStorage.setItem(STORAGE_KEY, JSON.stringify(rest));
  } catch (e) {
    console.log(e);
  }
};

const clearSavedData = (): void => {
  try {
    sessionStorage.removeItem(STORAGE_KEY);
  } catch (e) {
    console.log(e);
  }
};

const initialData: RegisterFormData = {
  email: '',
  password: '',
  name: '',
  birthday: null,
  gender: '',
  cityId: '',
  avatar: generateRandomAvatar(),
  avatarIsCustom: false,
  learnCategoryIds: [],
  subcategoriesIds: [],
  offerName: '',
  offerCategoryId: '',
  offerSubcategoryId: '',
  offerDescription: '',
  offerImages: [],
};

const parseStep = (raw: string | undefined): 1 | 2 | 3 => {
  const n = Number(raw);
  if (!Number.isFinite(n) || n < 1 || n > 3) return 1;
  return n as 1 | 2 | 3;
};

const detectFarthestStep = (data: RegisterFormData): 1 | 2 | 3 => {
  const step1Done = data.email.trim().length > 0 && data.password.length >= 8;
  if (!step1Done) return 1;

  const step2Done =
    data.name.trim().length >= 2 &&
    data.birthday !== null &&
    (data.gender === 'male' || data.gender === 'female') &&
    data.cityId.trim().length > 0 &&
    data.subcategoriesIds.length > 0;
  if (!step2Done) return 2;

  return 3;
};

