export const RegisterForm = () => {
  const navigate = useNavigate();
  const { step: stepParam } = useParams<{ step?: string }>();
  const step = parseStep(stepParam);

  const dispatch = useDispatch();
  const isLoading = useSelector(selectedUserIsResponse);
  const serverError = useSelector(selectedUserError);

  const [suppressServerError, setSuppressServerError] = useState(false);

  const [data, setData] = useState<RegisterFormData>(() => {
    const saved = loadSavedData();
    if (!saved.avatar) {
      saved.avatar = generateRandomAvatar();
    }
    return saved;
  });

  const [errors, setErrors] = useState<Record<string, string>>({});
  const [showPreview, setShowPreview] = useState(false);

  const didRedirect = useRef(false);
  useEffect(() => {
    if (didRedirect.current) return;
    didRedirect.current = true;

    if (step === 1) {
      const savedData = loadSavedData();
      const targetStep = detectFarthestStep(savedData);
      if (targetStep > 1) {
        navigate(`/registration/${targetStep}`, { replace: true });
      }
    }
  }, []);

  useEffect(() => {
    saveData(data);
  }, [data]);

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setErrors({});
    setSuppressServerError(true);
  }, [step]);

  const updateData = (patch: Partial<RegisterFormData>) => {
    setData((prev) => ({ ...prev, ...patch }));
  };

  const updateErrors = (patch: Record<string, string>) => {
    setErrors((prev) => ({ ...prev, ...patch }));
  };

  const validateStep = async (): Promise<boolean> => {
    try {
      const schema = stepSchemas[step - 1];
      await schema.validate(data, { abortEarly: false });
      setErrors({});
      return true;
    } catch (err: unknown) {
      if (err && typeof err === 'object' && 'inner' in err) {
        const yupError = err as { inner: Array<{ path?: string; message: string }> };
        const validationErrors = yupError.inner.reduce<Record<string, string>>((acc, e) => {
          if (e.path) acc[e.path] = e.message;
          return acc;
        }, {});
        setErrors(validationErrors);
      }
      return false;
    }
  };

  const handleNext = async () => {
    if (isLoading) return;

    const isValid = await validateStep();
    if (!isValid) return;

    if (step < 3) {
      navigate(`/registration/${step + 1}`);
      return;
    }

    setShowPreview(true);
  };

  const handleBack = () => {
    setErrors({});
    navigate(`/registration/${step - 1}`);
  };

  const handleConfirm = async () => {
    if (isLoading) return;
    console.log('uti');

    setSuppressServerError(false);

    const gender = data.gender as Gender;
    const avatar = data.avatar;

    const result = await dispatch(
      register({
        name: data.name,
        email: data.email,
        password: data.password,
        gender,
        birthday: (data.birthday as Date).toISOString(),
        cityId: data.cityId,
        subcategoriesIds: data.subcategoriesIds,
        avatar,
        description: '',
      })
    );

    if (register.fulfilled.match(result)) {
      const userId = result.payload.id;

      await dispatch(
        createOffer({
          userId,
          data: {
            name: data.offerName,
            description: data.offerDescription,
            subcategoryId: data.offerSubcategoryId,
            images: data.offerImages,
          },
        })
      );

      clearSavedData();
      setErrors({});
      setShowPreview(false);
    }
  };

  const illustration = STEP_ILLUSTRATIONS[step];
  const showServerError = !suppressServerError && !!serverError;

  return (
    <div className={`container ${styles.container}`}>
      <div className={styles.registerWrapper}>
        <div className={styles.stepper}>
          <span className={styles.stepperLabel}>Шаг {step} из 3</span>
          <div className={styles.stepperLines}>
            {([1, 2, 3] as const).map((n) => (
              <div
                key={n}
                className={`${styles.stepperLine} ${n <= step ? styles.stepperLineDone : ''}`}
              />
            ))}
          </div>
        </div>

        <div className={styles.registerCard}>
          <div className={styles.registerFormColumn}>
            {step === 1 && (
              <RegisterStep1
                data={data}
                onChange={updateData}
                errors={errors}
                onErrorChange={updateErrors}
              />
            )}
            {step === 2 && (
              <RegisterStep2
                data={data}
                onChange={updateData}
                errors={errors}
                onErrorChange={updateErrors}
              />
            )}
            {step === 3 && (
              <RegisterStep3
                data={data}
                onChange={updateData}
                errors={errors}
                onErrorChange={updateErrors}
              />
            )}

            {showServerError && <span className={styles.fieldError}>{serverError}</span>}

            <div className={`${styles.buttonGroup} ${step === 1 ? styles.buttonGroupSingle : ''}`}>
              {step > 1 && (
                <Button variant="secondary" onClick={handleBack} type="button" disabled={isLoading}>
                  Назад
                </Button>
              )}
              <Button
                variant="primary"
                onClick={handleNext}
                disabled={isLoading}
                loading={isLoading}
              >
                {step < 3 ? 'Далее' : 'Продолжить'}
              </Button>
            </div>
          </div>

          <div className={styles.registerSidebar}>
            <div className={styles.sidebarIllustration}>{illustration.icon}</div>
            <h3 className={styles.sidebarTitle}>{illustration.title}</h3>
            <p className={styles.sidebarSubtitle}>{illustration.subtitle}</p>
          </div>
        </div>

        <OfferPreviewModal
          isOpen={showPreview}
          data={data}
          onEdit={() => setShowPreview(false)}
          onConfirm={handleConfirm}
          isLoading={isLoading}
        />
      </div>
    </div>
  );
};
